"""Single-file badminton agent for the arena (generated by build_agent.py).

Reads one JSON observation per line on stdin and writes one JSON input window
per line on stdout.  Contains a line-by-line Python port of the public physics
(catalog.js / simulation.js) used for forward planning, plus the planner and
the decision brain.
"""
import json
import math
import os
import sys


# ===================== physics (engine_py) =====================

"""Python port of the public badminton simulation (catalog.js + simulation.js).

Used only for offline self-testing. The physics here is a line-by-line port of
the public rules source so that plans produced by the agent can be verified
before submission.
"""

RULES = {
    "hz": 20.0,
    "substeps": 4,
    "decisionFrames": 10,
    "courtLength": 13.4,
    "netX": 6.7,
    "netHeight": 1.55,
    "netThickness": 0.09,
    "ceiling": 11.0,
    "gravity": 9.8,
    "shuttleDrag": 0.025,
    "shuttleRadius": 0.07,
    "matchPoints": 11,
    "maxPoints": 15,
    "winBy": 2,
    "matchSeconds": 240,
    "serveFreeze": 0.8,
    "pointFreeze": 0.7,
    "playerSpeed": 3.7,
    "playerAccel": 26.0,
    "playerFriction": 12.0,
    "playerHeight": 1.8,
    "shoulderHeight": 1.45,
    "jumpSpeed": 5.3,
    "playerGravity": 22.0,
    "playerRadius": 0.22,
    "staminaRunDrain": 9.0,
    "staminaRegen": 6.0,
    "staminaSwingCost": 7.0,
    "staminaChargeDrain": 12.0,
    "staminaSprintDrain": 26.0,
    "sprintMultiplier": 1.45,
    "sprintMinStamina": 5.0,
    "chargeRate": 1.3,
    "chargeDecay": 6.0,
    "chargeMoveFactor": 0.45,
    "chargeBoost": 0.55,
    "swingFrames": 9,
    "swingWindup": 2,
    "swingActive": 5,
    "swingCooldown": 0.40,
    "hitLock": 0.30,
    "reachRadius": 0.38,
}
OVERHEAD = {"fromUp": 2.10, "fromFwd": 0.05, "toUp": 1.25, "toFwd": 0.80}
UNDERARM = {"fromUp": 0.28, "fromFwd": 0.50, "toUp": 1.22, "toFwd": 0.68}
SHOT = {
    "overheadSpeed": 9.0, "overheadBoost": 3.0, "overheadSmashBonus": 7.5,
    "overheadAngleLow": 0.60, "overheadAngleHigh": -0.42,
    "clearHeight": 1.80, "smashHeight": 2.35,
    "liftSpeed": 9.0, "liftBoost": 2.0, "liftAngle": 1.05,
}
SERVE = {"vx": 7.0, "vy": 6.2, "height": 1.35, "offset": 0.45, "targetFromNet": 3.2}

DT = 1.0 / RULES["hz"]
SUB = DT / RULES["substeps"]


def clamp(v, a, b):
    return a if v < a else (b if v > b else v)


def js_round(v):
    return math.floor(v + 0.5)


def round2(v):
    return js_round(v * 100) / 100.0


def sign(v):
    return 1 if v > 0 else (-1 if v < 0 else 0)


def home_x(team):
    return RULES["courtLength"] * 0.25 if team == 0 else RULES["courtLength"] * 0.75


def make_player(team, name):
    return {
        "id": "p%d" % team, "team": team, "index": team, "name": name,
        "x": home_x(team), "y": 0.0, "vx": 0.0, "vy": 0.0, "onGround": True,
        "facing": 1 if team == 0 else -1,
        "swing": 0, "swingElapsed": 0, "swingType": 1, "swingCd": 0.0,
        "lastHitFrame": -999, "held": neutral(), "sprinting": False,
        "hits": 0, "smashes": 0, "errors": 0, "points": 0,
        "stamina": 100.0, "charge": 0.0,
    }


def neutral():
    return {"move": 0.0, "jump": False, "swing": 0, "charge": False, "sprint": False}


def make_shuttle(x, y):
    return {"x": x, "y": y, "vx": 0.0, "vy": 0.0, "lastTeam": None, "owner": None,
            "lastHitFrame": -999, "alive": True, "trail": []}


class Match:
    def __init__(self, seed=1, players=None, match_id="test"):
        if players is None:
            players = [{"name": "A", "kind": "api"}, {"name": "B", "kind": "api"}]
        self.id = match_id
        self.seed = seed
        self.status = "playing"
        self.phase = "serve"
        self.winner = None
        self.reason = ""
        self.event_id = 0
        self.players = players
        self.frame = 0
        self.tick = 0
        self.score = [0, 0]
        self.server = 0
        self.serveTimer = 0
        self.pointTimer = 0
        self.rally = 0
        self.longestRally = 0
        self.lastPoint = None
        self.batsmen = [make_player(0, players[0]["name"]), make_player(1, players[1]["name"])]
        self.shuttle = None
        self.events = []
        self.pendingLanding = None
        self.begin_serve()

    # ---- events -------------------------------------------------------
    def emit(self, type_, data=None):
        self.event_id += 1
        ev = {"id": self.event_id, "t": round2(self.frame / RULES["hz"]),
              "frame": self.frame, "type": type_}
        if data:
            ev.update(data)
        self.events.append(ev)

    def begin_serve(self):
        p = self.batsmen[self.server]
        for b in self.batsmen:
            b.update({"x": home_x(b["team"]), "y": 0.0, "vx": 0.0, "vy": 0.0,
                      "onGround": True, "swing": 0, "swingElapsed": 0,
                      "swingCd": 0.0, "lastHitFrame": -999})
        self.shuttle = make_shuttle(p["x"] + p["facing"] * SERVE["offset"], SERVE["height"])
        self.shuttle["lastTeam"] = self.server
        self.phase = "serve"
        self.serveTimer = js_round(RULES["serveFreeze"] * RULES["hz"])
        self.rally = 0
        self.pendingLanding = None

    # ---- physics helpers ---------------------------------------------
    @staticmethod
    def in_swing_window(p):
        return (p["swing"] > 0 and p["swingElapsed"] >= RULES["swingWindup"]
                and p["swingElapsed"] < RULES["swingWindup"] + RULES["swingActive"])

    @staticmethod
    def racket_at(p, elapsed, swtype=None):
        if swtype is None:
            swtype = p["swingType"]
        frac = clamp(elapsed / float(RULES["swingFrames"]), 0.0, 1.0)
        arc = OVERHEAD if swtype > 0 else UNDERARM
        up = arc["fromUp"] + (arc["toUp"] - arc["fromUp"]) * frac
        fwd = arc["fromFwd"] + (arc["toFwd"] - arc["fromFwd"]) * frac
        return p["x"] + p["facing"] * fwd, p["y"] + up

    # ---- player -------------------------------------------------------
    def update_player(self, p):
        inp = p["held"] or {}
        try:
            move = clamp(float(inp.get("move", 0) or 0), -1.0, 1.0)
        except (TypeError, ValueError):
            move = 0.0
        accel = RULES["playerAccel"] if p["onGround"] else RULES["playerAccel"] * 0.35
        tired = 0.62 + 0.38 * p["stamina"] / 100.0
        charge_held = bool(inp.get("charge")) and p["onGround"] and p["stamina"] > 1
        sprint_held = (bool(inp.get("sprint")) and not charge_held and p["onGround"]
                       and move != 0 and p["stamina"] > RULES["sprintMinStamina"])
        if charge_held:
            p["charge"] = clamp(p["charge"] + RULES["chargeRate"] * DT, 0.0, 1.0)
        else:
            p["charge"] = max(0.0, p["charge"] - RULES["chargeDecay"] * DT)
        charged = 1.0 - (1.0 - RULES["chargeMoveFactor"]) * p["charge"]
        max_speed = RULES["playerSpeed"] * tired * charged * (RULES["sprintMultiplier"] if sprint_held else 1.0)
        p["sprinting"] = sprint_held

        if move != 0:
            p["vx"] += clamp(move * max_speed - p["vx"], -accel * DT, accel * DT)
        elif p["onGround"]:
            p["vx"] *= math.exp(-RULES["playerFriction"] * DT)
        else:
            p["vx"] *= math.exp(-1.5 * DT)

        running = abs(p["vx"]) > 3.2
        drain = 0.0
        if charge_held:
            drain += RULES["staminaChargeDrain"]
        if sprint_held:
            drain += RULES["staminaSprintDrain"]
        elif running:
            drain += RULES["staminaRunDrain"]
        if drain > 0:
            p["stamina"] = max(0.0, p["stamina"] - drain * DT)
        elif abs(p["vx"]) < 0.8 and p["onGround"]:
            p["stamina"] = min(100.0, p["stamina"] + RULES["staminaRegen"] * DT)

        if inp.get("jump") and p["onGround"] and p["stamina"] > 15:
            p["vy"] = RULES["jumpSpeed"]
            p["onGround"] = False
            p["stamina"] = max(0.0, p["stamina"] - 10)
        if not p["onGround"]:
            p["vy"] -= RULES["playerGravity"] * DT

        p["x"] += p["vx"] * DT
        p["y"] += p["vy"] * DT
        if p["y"] <= 0:
            p["y"] = 0.0
            p["vy"] = 0.0
            p["onGround"] = True

        lo = 0.35 if p["team"] == 0 else RULES["netX"] + 0.35
        hi = RULES["netX"] - 0.35 if p["team"] == 0 else RULES["courtLength"] - 0.35
        p["x"] = clamp(p["x"], lo, hi)

        if p["swingCd"] > 0:
            p["swingCd"] -= DT
        if p["swing"] > 0:
            p["swing"] -= 1
            p["swingElapsed"] += 1
        swing_dir = inp.get("swing", 0) or 0
        if isinstance(swing_dir, bool):
            swing_dir = 1 if swing_dir else 0
        if swing_dir != 0 and p["swing"] == 0 and p["swingCd"] <= 0:
            p["stamina"] = max(0.0, p["stamina"] - RULES["staminaSwingCost"])
            p["swing"] = RULES["swingFrames"]
            p["swingElapsed"] = 0
            p["swingType"] = 1 if swing_dir > 0 else -1
            p["swingCd"] = RULES["swingCooldown"] + RULES["swingFrames"] * DT

    # ---- shuttle ------------------------------------------------------
    def step_shuttle(self, dt):
        s = self.shuttle
        if not s["alive"]:
            return
        sp = math.hypot(s["vx"], s["vy"])
        drag = RULES["shuttleDrag"] * sp
        s["vx"] -= s["vx"] * drag * dt
        s["vy"] -= s["vy"] * drag * dt
        s["vy"] -= RULES["gravity"] * dt

        prev_x, prev_y = s["x"], s["y"]
        nx = s["x"] + s["vx"] * dt
        ny = s["y"] + s["vy"] * dt

        if ny > RULES["ceiling"]:
            ny = RULES["ceiling"]
            s["vy"] = -abs(s["vy"]) * 0.25

        crossed = (prev_x - RULES["netX"]) * (nx - RULES["netX"]) < 0
        if crossed:
            y_at_net = min(prev_y, ny)
            if y_at_net < RULES["netHeight"] + RULES["shuttleRadius"]:
                s["x"] = RULES["netX"] - sign(s["vx"]) * (RULES["netThickness"] + RULES["shuttleRadius"])
                s["vx"] *= -0.08
                s["vy"] *= 0.2
                self.emit("net", {"team": s["lastTeam"], "x": round2(s["x"]), "y": round2(s["y"])})
                return

        s["x"] = nx
        s["y"] = ny

        if s["x"] < -0.15 or s["x"] > RULES["courtLength"] + 0.15:
            s["alive"] = False
            s["vx"] = 0.0
            s["vy"] = 0.0
            self.pendingLanding = {"x": s["x"], "y": s["y"], "out": True}
            return
        if s["y"] <= RULES["shuttleRadius"]:
            s["y"] = RULES["shuttleRadius"]
            s["alive"] = False
            s["vx"] = 0.0
            s["vy"] = 0.0
            self.pendingLanding = {"x": s["x"], "y": 0.0}

    # ---- shot solving --------------------------------------------------
    @staticmethod
    def flight_landing(x, y, vx, vy):
        dt = SUB
        t = 0.0
        while t < 5.0:
            sp = math.hypot(vx, vy)
            vx -= vx * RULES["shuttleDrag"] * sp * dt
            vy -= vy * RULES["shuttleDrag"] * sp * dt
            vy -= RULES["gravity"] * dt
            x += vx * dt
            y += vy * dt
            if y > RULES["ceiling"]:
                y = RULES["ceiling"]
                vy = -abs(vy) * 0.25
            if y <= RULES["shuttleRadius"]:
                return x
            if x < -0.5 or x > RULES["courtLength"] + 0.5:
                return x
            t += dt
        return x

    @staticmethod
    def solve_speed(x0, y0, angle, dir_, target_x):
        lo, hi = 5.0, 34.0
        for _ in range(14):
            mid = (lo + hi) / 2.0
            land = Match.flight_landing(x0, y0, dir_ * mid * math.cos(angle), mid * math.sin(angle))
            if (land - target_x) * dir_ < 0:
                lo = mid
            else:
                hi = mid
        return (lo + hi) / 2.0

    @staticmethod
    def shot_trace(x0, y0, angle, speed, dir_):
        x, y = x0, y0
        vx = dir_ * speed * math.cos(angle)
        vy = speed * math.sin(angle)
        dt = SUB
        net_y = None
        t = 0.0
        while t < 5.0:
            sp = math.hypot(vx, vy)
            vx -= vx * RULES["shuttleDrag"] * sp * dt
            vy -= vy * RULES["shuttleDrag"] * sp * dt
            vy -= RULES["gravity"] * dt
            px, py = x, y
            x += vx * dt
            y += vy * dt
            if net_y is None and (px - RULES["netX"]) * (x - RULES["netX"]) <= 0 and abs(x - px) > 1e-9:
                f = (RULES["netX"] - px) / (x - px)
                net_y = py + (y - py) * f
            if y > RULES["ceiling"]:
                y = RULES["ceiling"]
                vy = -abs(vy) * 0.25
            net_hit = net_y is not None and net_y < RULES["netHeight"] + RULES["shuttleRadius"] + 0.03
            if y <= RULES["shuttleRadius"]:
                return {"netY": net_y, "landX": x, "netHit": net_hit}
            if x < -0.2 or x > RULES["courtLength"] + 0.2:
                return {"netY": net_y, "landX": x, "netHit": net_hit}
            t += dt
        net_hit = net_y is not None and net_y < RULES["netHeight"] + RULES["shuttleRadius"] + 0.03
        return {"netY": net_y, "landX": x, "netHit": net_hit}

    @staticmethod
    def choose_shot(x, y, dir_, kind, target):
        ranges = {
            "smash": [-0.42, -0.30, -0.18, -0.06, 0.06, 0.16, 0.26, 0.34],
            "clear": [0.60, 0.72, 0.85],
            "drop": [0.42, 0.55, 0.68],
            "lift": [1.05, 1.20],
        }
        for angle in ranges[kind]:
            speed = Match.solve_speed(x, y, angle, dir_, target)
            tr = Match.shot_trace(x, y, angle, speed, dir_)
            if not tr["netHit"] and -0.05 < tr["landX"] < RULES["courtLength"] + 0.05:
                return angle, speed
        angle = -0.42 if kind == "smash" else (0.75 if kind == "clear" else (0.60 if kind == "drop" else 1.15))
        return angle, Match.solve_speed(x, y, angle, dir_, target)

    @staticmethod
    def shot_kind_and_target(sx, sy, swing_type, facing, opp_x):
        """Replicates the kind/target selection inside strike()."""
        dir_ = facing
        if swing_type > 0:
            t = clamp((sy - SHOT["clearHeight"]) / (SHOT["smashHeight"] - SHOT["clearHeight"]), 0.0, 1.0)
            dist_net = abs(sx - RULES["netX"])
            near = clamp(1.0 - (dist_net - 3.2) / 2.5, 0.0, 1.0)
            smash = t * near
            opp_deep = abs(opp_x - RULES["netX"]) > 3.0
            if smash > 0.55:
                kind = "smash"
                short_x = RULES["netX"] + dir_ * 1.6
                deep_x = RULES["courtLength"] - 1.0 if dir_ > 0 else 1.0
                target = short_x if abs(short_x - opp_x) >= abs(deep_x - opp_x) else deep_x
            elif t > 0.5 and opp_deep and dist_net > 2.6:
                kind = "drop"
                target = RULES["netX"] + dir_ * 2.7
            else:
                kind = "clear"
                target = 11.9 if dir_ > 0 else RULES["courtLength"] - 11.9
        else:
            kind = "lift"
            target = 11.4 if dir_ > 0 else RULES["courtLength"] - 11.4
        return kind, target

    # ---- strike / hit --------------------------------------------------
    def strike(self, p, sx, sy):
        s = self.shuttle
        forward = clamp((p["held"].get("move", 0) or 0) * p["facing"], 0.0, 1.0)
        opp = self.batsmen[1 - p["team"]]
        kind, target = self.shot_kind_and_target(sx, sy, p["swingType"], p["facing"], opp["x"])
        target += p["facing"] * forward * 0.6
        angle, speed = self.choose_shot(sx, sy, p["facing"], kind, target)
        speed *= 1.0 + RULES["chargeBoost"] * p["charge"]
        p["charge"] = 0.0
        s["vx"] = p["facing"] * speed * math.cos(angle)
        s["vy"] = speed * math.sin(angle)
        s["x"] = sx
        s["y"] = sy
        s["lastTeam"] = p["team"]
        s["owner"] = p["id"]
        s["lastHitFrame"] = self.frame
        s["trail"] = []
        p["lastHitFrame"] = self.frame
        p["hits"] += 1
        self.rally += 1
        self.longestRally = max(self.longestRally, self.rally)
        self.emit("hit", {"team": p["team"], "kind": kind, "x": round2(sx),
                          "y": round2(sy), "speed": round2(speed)})

    def try_hit(self, p, sx, sy):
        if not self.in_swing_window(p):
            return False
        if self.frame - p["lastHitFrame"] < RULES["hitLock"] * RULES["hz"]:
            return False
        s = self.shuttle
        if not s["alive"]:
            return False
        if p["team"] == 0 and s["x"] > RULES["netX"] + 0.3:
            return False
        if p["team"] == 1 and s["x"] < RULES["netX"] - 0.3:
            return False
        rx, ry = self.racket_at(p, p["swingElapsed"], p["swingType"])
        reach = RULES["reachRadius"] * (0.82 + 0.18 * p["stamina"] / 100.0)
        if math.hypot(sx - rx, sy - ry) > reach:
            return False
        self.strike(p, sx, sy)
        return True

    # ---- point ---------------------------------------------------------
    def resolve_point(self):
        land = self.pendingLanding
        if not land:
            return
        self.pendingLanding = None
        s = self.shuttle
        last = 0 if s["lastTeam"] is None else s["lastTeam"]
        if land.get("out"):
            winner = 1 - last
            reason = "出界"
        else:
            side = 0 if land["x"] < RULES["netX"] else 1
            winner = 1 - last if side == last else last
            reason = "落在自己半场" if side == last else "落在对方半场"
        self.score[winner] += 1
        self.batsmen[winner]["points"] += 1
        self.server = winner
        self.lastPoint = {"winner": winner, "reason": reason, "rally": self.rally,
                          "x": round2(land["x"]), "out": bool(land.get("out"))}
        self.emit("point", {"team": winner, "score": list(self.score), "reason": reason,
                            "rally": self.rally, "x": round2(land["x"])})
        a, b = self.score
        hi, lo = max(a, b), min(a, b)
        if (hi >= RULES["matchPoints"] and hi - lo >= RULES["winBy"]) or hi >= RULES["maxPoints"]:
            self.finish(0 if a > b else 1, "比分 %d:%d" % (a, b))
            return
        self.phase = "point"
        self.pointTimer = js_round(RULES["pointFreeze"] * RULES["hz"])

    def finish(self, winner, reason):
        if self.status == "finished":
            return
        self.status = "finished"
        self.phase = "finished"
        self.winner = winner
        self.reason = reason
        self.emit("finish", {"team": winner, "reason": reason, "score": list(self.score)})

    # ---- main step -----------------------------------------------------
    def step(self):
        if self.status != "playing":
            return
        self.frame += 1
        self.tick += 1

        if self.phase == "serve":
            self.serveTimer -= 1
            if self.serveTimer <= 0:
                p = self.batsmen[self.server]
                angle = 0.72
                target = RULES["netX"] + p["facing"] * SERVE["targetFromNet"]
                speed = self.solve_speed(self.shuttle["x"], self.shuttle["y"], angle, p["facing"], target)
                self.shuttle["vx"] = p["facing"] * speed * math.cos(angle)
                self.shuttle["vy"] = speed * math.sin(angle)
                self.shuttle["lastTeam"] = self.server
                self.shuttle["lastHitFrame"] = self.frame
                self.phase = "rally"
                self.emit("serve", {"team": self.server})

        for p in self.batsmen:
            self.update_player(p)

        if self.phase == "rally":
            s = self.shuttle
            for _ in range(RULES["substeps"]):
                self.step_shuttle(SUB)
                for p in self.batsmen:
                    if self.try_hit(p, s["x"], s["y"]):
                        break
                if not s["alive"] or self.pendingLanding:
                    break
            if s["alive"]:
                s["trail"].append({"x": round2(s["x"]), "y": round2(s["y"])})
                if len(s["trail"]) > 14:
                    s["trail"].pop(0)
            if self.pendingLanding:
                self.resolve_point()
        elif self.phase == "point":
            self.pointTimer -= 1
            if self.pointTimer <= 0:
                self.begin_serve()

        if self.status == "playing" and self.frame >= RULES["matchSeconds"] * RULES["hz"]:
            a, b = self.score
            if a == b:
                self.finish(None, "时间到，%d:%d 平局" % (a, b))
            else:
                self.finish(0 if a > b else 1, "时间到，%d:%d" % (max(a, b), min(a, b)))

    # ---- observation ---------------------------------------------------
    def public_player(self, p):
        return {
            "id": p["id"], "team": p["team"], "index": p["index"], "name": p["name"],
            "x": round2(p["x"]), "y": round2(p["y"]), "vx": round2(p["vx"]), "vy": round2(p["vy"]),
            "onGround": p["onGround"], "facing": p["facing"], "sprinting": bool(p["sprinting"]),
            "swing": p["swing"], "swingElapsed": p["swingElapsed"], "swingType": p["swingType"],
            "swinging": self.in_swing_window(p),
            "swingCd": round2(max(0.0, p["swingCd"])),
            "stamina": round2(p["stamina"]), "charge": round2(p["charge"]),
            "hits": p["hits"], "smashes": p["smashes"], "points": p["points"],
        }

    def view(self, viewer=None):
        s = self.shuttle
        return {
            "id": self.id, "seed": self.seed, "tick": self.tick, "frame": self.frame,
            "status": self.status, "phase": self.phase, "winner": self.winner,
            "reason": self.reason, "yourPlayer": viewer,
            "players": [dict(p) for p in self.players],
            "score": list(self.score), "server": self.server,
            "serveLeft": round2(max(0.0, self.serveTimer / RULES["hz"])),
            "pointLeft": round2(max(0.0, self.pointTimer / RULES["hz"])),
            "rally": self.rally, "longestRally": self.longestRally,
            "lastPoint": self.lastPoint,
            "timeLeft": round2(max(0.0, RULES["matchSeconds"] - self.frame / RULES["hz"])),
            "batsmen": [self.public_player(p) for p in self.batsmen],
            "shuttle": None if s is None else {
                "x": round2(s["x"]), "y": round2(s["y"]), "vx": round2(s["vx"]),
                "vy": round2(s["vy"]), "alive": s["alive"], "lastTeam": s["lastTeam"],
                "owner": s["owner"], "trail": s["trail"][-14:],
            },
            "court": {"length": RULES["courtLength"], "netX": RULES["netX"],
                      "netHeight": RULES["netHeight"], "ceiling": RULES["ceiling"]},
            "rules": dict(RULES),
            "events": self.events[-60:],
        }


def normalize_unit_input(inp):
    out = neutral()
    if inp is None:
        return out
    if not isinstance(inp, dict):
        raise ValueError("input must be an object")
    if inp.get("move") is not None:
        v = float(inp["move"])
        if v != v or v in (float("inf"), float("-inf")):
            raise ValueError("bad move")
        out["move"] = clamp(v, -1.0, 1.0)
    out["jump"] = bool(inp.get("jump"))
    out["charge"] = bool(inp.get("charge"))
    out["sprint"] = bool(inp.get("sprint"))
    if inp.get("swing") is not None:
        sw = inp["swing"]
        if isinstance(sw, bool):
            out["swing"] = 1 if sw else 0
        else:
            v = float(sw)
            out["swing"] = 1 if v > 0.1 else (-1 if v < -0.1 else 0)
    return out


def normalize_frame(frame):
    if isinstance(frame, list):
        if len(frame) != 1:
            raise ValueError("each frame must hold exactly 1 player")
        return [normalize_unit_input(frame[0])]
    return [normalize_unit_input(frame)]


def advance_window(g, windows):
    steps = 0
    for i in range(RULES["decisionFrames"]):
        if g.status != "playing":
            break
        for b in g.batsmen:
            win = windows[b["team"]] if b["team"] < len(windows) else None
            frame = win[i] if win and i < len(win) else None
            b["held"] = (frame[0] if frame else neutral())
        g.step()
        steps += 1
    return steps


def run_match(agent0, agent1, seed=1, match_id="test", max_windows=2000, on_window=None):
    g = Match(seed=seed, match_id=match_id)
    w = 0
    while g.status == "playing" and w < max_windows:
        o0 = g.view(0)
        o1 = g.view(1)
        w0 = agent0.act(o0)
        w1 = agent1.act(o1)
        win0 = [normalize_frame(f) for f in w0]
        win1 = [normalize_frame(f) for f in w1]
        advance_window(g, [win0, win1])
        w += 1
        if on_window:
            on_window(g, w)
    return g

# module alias so the ported modules can keep using E.*
E = sys.modules[__name__]


# ===================== planner =====================

"""Planning core for the badminton agent (offline development version).

Depends on engine_py for the exact physics. At submission time this module is
bundled with engine_py into a single self-contained agent.py.
"""


R = E.RULES
DT = E.DT
SUB = E.SUB


def clamp(v, a, b):
    return a if v < a else (b if v > b else v)


# --------------------------------------------------------------------------
# Racket geometry
# --------------------------------------------------------------------------
def racket_offsets(elapsed, swtype):
    frac = clamp(elapsed / float(R["swingFrames"]), 0.0, 1.0)
    arc = E.OVERHEAD if swtype > 0 else E.UNDERARM
    up = arc["fromUp"] + (arc["toUp"] - arc["fromUp"]) * frac
    fwd = arc["fromFwd"] + (arc["toFwd"] - arc["fromFwd"]) * frac
    return up, fwd


def reach_of(stamina):
    return R["reachRadius"] * (0.82 + 0.18 * stamina / 100.0)


def max_speed_of(stamina):
    return R["playerSpeed"] * (0.62 + 0.38 * stamina / 100.0)


# --------------------------------------------------------------------------
# Shuttle prediction
# --------------------------------------------------------------------------
def shuttle_step(state, dt, net=True):
    """Advance a shuttle dict by dt. Returns 'net' if it hit the net."""
    x, y, vx, vy = state["x"], state["y"], state["vx"], state["vy"]
    sp = math.hypot(vx, vy)
    drag = R["shuttleDrag"] * sp
    vx -= vx * drag * dt
    vy -= vy * drag * dt
    vy -= R["gravity"] * dt
    prev_x, prev_y = x, y
    nx = x + vx * dt
    ny = y + vy * dt
    if ny > R["ceiling"]:
        ny = R["ceiling"]
        vy = -abs(vy) * 0.25
    if net:
        crossed = (prev_x - R["netX"]) * (nx - R["netX"]) < 0
        if crossed:
            y_at_net = min(prev_y, ny)
            if y_at_net < R["netHeight"] + R["shuttleRadius"]:
                x = R["netX"] - E.sign(vx) * (R["netThickness"] + R["shuttleRadius"])
                vx *= -0.08
                vy *= 0.2
                state.update(x=x, y=y, vx=vx, vy=vy, alive=True)
                return "net"
    x, y = nx, ny
    landed = False
    if x < -0.15 or x > R["courtLength"] + 0.15:
        landed = True
        state.update(x=x, y=y, vx=0.0, vy=0.0, alive=False)
        return "out"
    if y <= R["shuttleRadius"]:
        y = R["shuttleRadius"]
        landed = True
        state.update(x=x, y=y, vx=0.0, vy=0.0, alive=False)
        return "land"
    state.update(x=x, y=y, vx=vx, vy=vy, alive=True)
    return None


def predict_shuttle(shuttle, nframes):
    """Predict the shuttle for nframes frames.

    Returns list of length nframes+1; entry f is the list of substep samples
    (x, y, alive) taken during frame f (index 0 = current state, empty list).
    """
    st = {k: shuttle[k] for k in ("x", "y", "vx", "vy", "alive")}
    out = [[(st["x"], st["y"], st["alive"])]]
    for f in range(1, nframes + 1):
        samples = []
        for _ in range(R["substeps"]):
            if not st["alive"]:
                samples.append((st["x"], st["y"], False))
                continue
            res = shuttle_step(st, SUB)
            samples.append((st["x"], st["y"], st["alive"]))
            if res in ("land", "out"):
                break
        out.append(samples)
        if not st["alive"]:
            # pad remaining frames
            for _ in range(nframes - f):
                out.append([(st["x"], st["y"], False)])
            break
    while len(out) < nframes + 1:
        out.append([(st["x"], st["y"], False)])
    return out


def predict_serve(shuttle, release_in_frames, server_facing, nframes):
    """Predict a serve from the frozen shuttle state until nframes frames.

    release_in_frames: how many frames until the serve leaves the server's
    racket (0 or negative means it has already been released).
    """
    st = {k: shuttle[k] for k in ("x", "y", "vx", "vy", "alive")}
    out = [[(st["x"], st["y"], st["alive"])]]
    target = R["netX"] + server_facing * E.SERVE["targetFromNet"]
    release = max(1, int(release_in_frames))
    for f in range(1, nframes + 1):
        if f < release:
            # frozen on the server's racket
            out.append([(st["x"], st["y"], st["alive"])])
            continue
        if f == release:
            speed = E.Match.solve_speed(st["x"], st["y"], 0.72, server_facing, target)
            st["vx"] = server_facing * speed * math.cos(0.72)
            st["vy"] = speed * math.sin(0.72)
        samples = []
        for _ in range(R["substeps"]):
            if not st["alive"]:
                samples.append((st["x"], st["y"], False))
                continue
            res = shuttle_step(st, SUB)
            samples.append((st["x"], st["y"], st["alive"]))
            if res in ("land", "out"):
                break
        out.append(samples)
        if not st["alive"]:
            for _ in range(nframes - f):
                out.append([(st["x"], st["y"], False)])
            break
    while len(out) < nframes + 1:
        out.append([(st["x"], st["y"], False)])
    return out


# --------------------------------------------------------------------------
# Player simulation
# --------------------------------------------------------------------------
def player_state_from_obs(b, team):
    p = E.make_player(team, "me")
    for k in ("x", "y", "vx", "vy", "onGround", "facing", "swing", "swingElapsed",
              "swingType", "swingCd", "stamina", "charge"):
        if k in b:
            p[k] = b[k]
    p["stamina"] = float(b.get("stamina", 100.0))
    p["charge"] = float(b.get("charge", 0.0))
    p["lastHitFrame"] = -999
    return p


class DummyMatch:
    """Minimal host object so we can reuse Match.update_player."""
    def __init__(self):
        self.frame = 0
        self.events = []
        self.event_id = 0
        self.batsmen = []
        self.shuttle = None
        self.pendingLanding = None

    def emit(self, *a, **k):
        pass


def sim_player(p, inputs, nframes):
    """Simulate a player for nframes with the given per-frame input dicts.

    Returns a list of snapshots (dicts) per frame, index 0 = start state.
    """
    host = DummyMatch()
    q = {k: (dict(v) if isinstance(v, dict) else v) for k, v in p.items()}
    traj = [dict(q)]
    for i in range(nframes):
        q["held"] = inputs[i] if i < len(inputs) else E.neutral()
        E.Match.update_player(host, q)
        traj.append(dict(q))
    return traj


def servo_inputs(p, target_x, at_frame, jump_at=None, nframes=None, hold_after=False,
                 allow_sprint=True):
    """Produce per-frame inputs that bring the player to target_x at at_frame."""
    if nframes is None:
        nframes = max(at_frame, 1)
    p0 = p
    inputs = []
    for i in range(nframes):
        f = i + 1
        left = at_frame - i
        dx = target_x - p0["x"]
        base = max_speed_of(p0["stamina"])
        can_sprint = allow_sprint and p0["stamina"] > 18 and p0["onGround"]
        top = base * (R["sprintMultiplier"] if can_sprint else 1.0)
        if left > 0:
            v_des = clamp(dx / (left * DT), -top, top)
        else:
            v_des = 0.0
        sprint = abs(v_des) > base + 0.03
        denom = base * (R["sprintMultiplier"] if sprint else 1.0)
        mv = clamp(v_des / denom, -1.0, 1.0) if denom > 1e-6 else 0.0
        if hold_after and f > at_frame:
            mv = 0.0
            sprint = False
        inp = {"move": mv, "sprint": sprint}
        if jump_at is not None and f == jump_at:
            inp["jump"] = True
        inputs.append(inp)
        # advance a copy to keep the servo state current
        q = dict(p0)
        q["held"] = inp
        E.Match.update_player(DummyMatch(), q)
        p0 = q
    return inputs


def reach_at(p, frames):
    """Fastest forward/backward reachable x after `frames` frames."""
    fwd = servo_inputs(p, 100.0, frames)
    back = servo_inputs(p, -100.0, frames)
    tf = sim_player(p, fwd, frames)
    tb = sim_player(p, back, frames)
    return tf[-1]["x"], tb[-1]["x"]


def plan_control(p, target_x, at_frame, nframes, jump_at=None, hold_after=True):
    """Servo to target_x at at_frame, with one correction pass, then verification."""
    inputs = servo_inputs(p, target_x, at_frame, jump_at, nframes, hold_after)
    for _ in range(2):
        traj = sim_player(p, inputs, nframes)
        if at_frame >= len(traj):
            break
        actual = traj[at_frame]["x"]
        err = target_x - actual
        if abs(err) < 0.005:
            break
        target_x2 = target_x + err
        inputs = servo_inputs(p, target_x2, at_frame, jump_at, nframes, hold_after)
        target_x = target_x2
    return inputs


# --------------------------------------------------------------------------
# Shot evaluation
# --------------------------------------------------------------------------
def shot_from_contact(sx, sy, swtype, facing, opp_x, charge=0.0, forward=0.0):
    kind, target = E.Match.shot_kind_and_target(sx, sy, swtype, facing, opp_x)
    target += facing * clamp(forward, 0.0, 1.0) * 0.6
    angle, speed = E.Match.choose_shot(sx, sy, facing, kind, target)
    speed *= 1.0 + R["chargeBoost"] * charge
    return {"kind": kind, "target": target, "angle": angle, "speed": speed}


def simulate_shot(sx, sy, shot, facing, nframes=60):
    """Full flight samples of a struck shuttle: list of (frame, x, y)."""
    st = {"x": sx, "y": sy,
          "vx": facing * shot["speed"] * math.cos(shot["angle"]),
          "vy": shot["speed"] * math.sin(shot["angle"]),
          "alive": True}
    out = []
    for f in range(1, nframes + 1):
        for _ in range(R["substeps"]):
            if not st["alive"]:
                break
            res = shuttle_step(st, SUB)
            if res in ("land", "out"):
                break
        out.append((f, st["x"], st["y"]))
        if not st["alive"]:
            break
    return out


def opponent_can_reach(traj, opp_x, opp_stamina, team_of_opp, extra_move=0.0):
    """Rough check whether the opponent can intercept the shot before it lands."""
    maxs = max_speed_of(opp_stamina)
    reach = reach_of(opp_stamina)
    for (f, x, y) in traj:
        t = f * DT
        # ball must be on the opponent's side to be hittable
        if team_of_opp == 0 and x > R["netX"] + 0.3:
            continue
        if team_of_opp == 1 and x < R["netX"] - 0.3:
            continue
        if y > 2.35 or y < 0.05:
            continue
        # they can be anywhere within maxs*t of their current x (plus a bit)
        d = abs(x - opp_x)
        travel = maxs * t + 0.5 * R["playerAccel"] * min(t, maxs / R["playerAccel"]) ** 2
        if d <= travel + reach + 0.55 + extra_move:
            return True, f
    return False, None


# --------------------------------------------------------------------------
# Interception planning
# --------------------------------------------------------------------------
def best_contacts(ball_pred, team, p, opp, horizon, stamina_hint=None):
    """Enumerate candidate (frame, elapsed, swtype) contacts for the player.

    Returns a list of dicts sorted by (score desc).
    """
    facing = p["facing"]
    st = stamina_hint if stamina_hint is not None else p["stamina"]
    reach = reach_of(st)
    cands = []
    for t in range(1, min(horizon, len(ball_pred) - 1) + 1):
        samples = [s for s in ball_pred[t] if s[2]]
        if not samples:
            continue
        for swtype in (1, -1):
            for e in range(R["swingWindup"], R["swingWindup"] + R["swingActive"]):
                up, fwd = racket_offsets(e, swtype)
                best = None
                for (bx, by, alive) in samples:
                    if team == 0 and bx > R["netX"] + 0.3:
                        continue
                    if team == 1 and bx < R["netX"] - 0.3:
                        continue
                    # feet height: assume ground unless already airborne
                    py = p["y"]
                    dy = by - (py + up)
                    if abs(dy) > reach:
                        continue
                    half = math.sqrt(max(0.0, reach * reach - dy * dy))
                    px = bx - facing * fwd
                    if best is None or half > best[2]:
                        best = (px, half, half)
                if best is None:
                    continue
                cands.append({"t": t, "e": e, "swtype": swtype, "px": best[0],
                              "margin": best[1]})
    return cands

# ===================== brain =====================

"""Agent brain (development version). Bundled into agent.py for submission."""


R = E.RULES
DT = E.DT
SUB = E.SUB

KIND_BASE = {"smash": 100.0, "drop": 62.0, "clear": 38.0, "lift": 22.0}

DEBUG = bool(os.environ.get("BAD_DEBUG"))


def log(*a):
    if DEBUG:
        print(*a, file=sys.stderr)


def neutral_window():
    return [E.neutral() for _ in range(10)]


def opp_x_at(opp, t):
    x = opp["x"] + opp["vx"] * t * DT
    if opp["team"] == 0:
        return clamp(x, 0.35, R["netX"] - 0.35)
    return clamp(x, R["netX"] + 0.35, R["courtLength"] - 0.35)


def in_window(p):
    return (p["swing"] > 0 and p["swingElapsed"] >= R["swingWindup"]
            and p["swingElapsed"] < R["swingWindup"] + R["swingActive"])


def shot_frames(sx, sy, shot, facing, nframes):
    """Substep samples per frame of a struck shuttle (index 0 = contact frame)."""
    st = {"x": sx, "y": sy,
          "vx": facing * shot["speed"] * math.cos(shot["angle"]),
          "vy": shot["speed"] * math.sin(shot["angle"]),
          "alive": True}
    out = [[(sx, sy, True)]]
    for f in range(1, nframes + 1):
        samples = []
        for _ in range(R["substeps"]):
            if not st["alive"]:
                samples.append((st["x"], st["y"], False))
                continue
            res = shuttle_step(st, SUB)
            samples.append((st["x"], st["y"], st["alive"]))
            if res in ("land", "out"):
                break
        out.append(samples)
        if not st["alive"]:
            for _ in range(nframes - f):
                out.append([(st["x"], st["y"], False)])
            break
    while len(out) < nframes + 1:
        out.append([(st["x"], st["y"], False)])
    return out


class Brain:
    def __init__(self, def_mode=None, smash_lover=False, no_sprint=False, nudge=False, learn=True, clear_lover=False):
        self.debug_hits = []
        self.def_mode = def_mode or os.environ.get("BAD_DEF", "mid")
        self.smash_lover = smash_lover
        self.clear_lover = clear_lover
        self.no_sprint = no_sprint
        self.nudge = nudge
        self.learn = learn
        self.seen_event = 0
        self.return_contacts = []       # (x, y, offset) of opponent serve returns
        self.serve_release = None       # frame our current serve left the racket
        self.serve_hit_pending = False

    # ------------------------------------------------------------------
    def act(self, obs):
        try:
            return self._act(obs)
        except Exception:
            if DEBUG:
                import traceback
                traceback.print_exc()
            return neutral_window()

    def _act(self, obs):
        team = obs.get("yourPlayer")
        if obs.get("status") != "playing" or team is None:
            return neutral_window()
        self._observe(obs, team)
        me = player_state_from_obs(obs["batsmen"][team], team)
        opp = player_state_from_obs(obs["batsmen"][1 - team], 1 - team)
        phase = obs.get("phase")
        if phase == "serve":
            if obs.get("server") == team:
                return self._defend(obs, me, opp, team)
            return self._receive_serve(obs, me, opp, team)
        if phase == "rally":
            ball = obs.get("shuttle")
            if not ball or not ball.get("alive"):
                return neutral_window()
            if ball.get("lastTeam") == team:
                return self._defend(obs, me, opp, team)
            return self._rally_plan(obs, me, opp, team)
        return neutral_window()

    def _observe(self, obs, team):
        """Track the serve release frame and the opponent's serve-return hits."""
        try:
            frame = obs.get("frame")
            if frame is None:
                return
            if obs.get("phase") == "serve" and obs.get("server") == team:
                rel = int(round(float(obs.get("serveLeft", 0)) * R["hz"]))
                self.serve_release = frame + rel
                self.serve_hit_pending = True
            for e in obs.get("events") or []:
                eid = e.get("id")
                if eid is None or eid <= self.seen_event:
                    continue
                self.seen_event = eid
                if (e.get("type") == "hit" and e.get("team") == 1 - team
                        and getattr(self, "serve_hit_pending", False)
                        and self.serve_release is not None and e.get("frame") is not None):
                    off = e["frame"] - self.serve_release
                    cx, cy = e.get("x"), e.get("y")
                    self.serve_hit_pending = False
                    if 0 < off < 40 and cx is not None and cy is not None:
                        self.return_contacts.append((cx, cy, off))
                        self.return_contacts = self.return_contacts[-6:]
        except Exception:
            pass

    def _learned_contact(self):
        """A stable opponent serve-return contact, if the last two agree."""
        rc = self.return_contacts
        if len(rc) < 2:
            return None
        x1, y1, o1 = rc[-2]
        x2, y2, o2 = rc[-1]
        if abs(x1 - x2) > 0.35 or abs(y1 - y2) > 0.35 or abs(o1 - o2) > 3:
            return None
        return (x2, y2, o2)

    # ------------------------------------------------------------------
    # Candidate enumeration
    # ------------------------------------------------------------------
    def _candidates(self, ball_pred, me, team, horizon):
        facing = me["facing"]
        reach = reach_of(me["stamina"])
        cands = []
        midswing = me["swing"] > 0
        for t in range(1, min(horizon, len(ball_pred) - 1) + 1):
            samples = [s for s in ball_pred[t] if s[2]]
            if not samples:
                break
            if midswing:
                e = me["swingElapsed"] + t
                if e < R["swingWindup"] or e >= R["swingWindup"] + R["swingActive"]:
                    continue
                types = (me["swingType"],)
                elist = (e,)
            else:
                types = (1, -1)
                elist = [x for x in range(R["swingWindup"], R["swingWindup"] + R["swingActive"])
                         if t - x >= 1]
            py = me["y"]
            for swtype in types:
                for e in elist:
                    up, fwd = racket_offsets(e, swtype)
                    best = None
                    for (bx, by, alive) in samples:
                        if team == 0 and bx > R["netX"] + 0.3:
                            continue
                        if team == 1 and bx < R["netX"] - 0.3:
                            continue
                        dy = by - (py + up)
                        if abs(dy) > reach:
                            continue
                        half = math.sqrt(max(0.0, reach * reach - dy * dy))
                        if best is None or half > best[2]:
                            best = (bx - facing * fwd, half, half, bx, by)
                    if best is None:
                        continue
                    lo = 0.35 if team == 0 else R["netX"] + 0.35
                    hi = R["netX"] - 0.35 if team == 0 else R["courtLength"] - 0.35
                    cands.append({"t": t, "e": e, "swtype": swtype,
                                  "px": clamp(best[0], lo, hi),
                                  "margin": best[1], "bx": best[3], "by": best[4]})
        return cands

    def _reachable_range(self, me, t):
        fwd = servo_inputs(me, 100.0, t)
        back = servo_inputs(me, -100.0, t)
        xf = sim_player(me, fwd, t)[-1]["x"]
        xb = sim_player(me, back, t)[-1]["x"]
        return min(xb, xf), max(xb, xf)

    def _eval_contact(self, cand, me, opp, team, ball_pred):
        facing = me["facing"]
        t = cand["t"]
        ox = opp_x_at(opp, t)
        shot = shot_from_contact(cand["bx"], cand["by"], cand["swtype"], facing, ox)
        traj = simulate_shot(cand["bx"], cand["by"], shot, facing, nframes=60)
        kind = shot["kind"]
        score = KIND_BASE.get(kind, 20.0)
        if self.clear_lover:
            score += {"smash": -150.0, "drop": 0.0, "clear": 120.0, "lift": 110.0}.get(kind, 0.0)
        dist_net = abs(cand["bx"] - R["netX"])
        if kind == "smash":
            score += (cand["by"] - 2.0) * 25.0
            score += max(0.0, 3.2 - dist_net) * 4.0
        elif kind == "drop":
            score += max(0.0, 3.0 - dist_net) * 6.0
        can, f = opponent_can_reach(traj, ox, opp["stamina"], opp["team"])
        if not can:
            score += 130.0
        else:
            score -= 10.0
        # A shot that crosses the net at blockable height while the opponent is
        # camping near the net is likely to come straight back: penalise it.
        cross_h = None
        prev = (cand["bx"], cand["by"])
        for (f, x, y) in traj:
            if (prev[0] - R["netX"]) * (x - R["netX"]) <= 0 and abs(x - prev[0]) > 1e-9:
                fr = (R["netX"] - prev[0]) / (x - prev[0])
                cross_h = prev[1] + (y - prev[1]) * fr
                break
            prev = (x, y)
        if (not self.smash_lover) and cross_h is not None and abs(ox - R["netX"]) < 1.9 and cross_h < 2.25:
            score -= 85.0
        # Reject shots that hit the net / land on our own side / fly out: the
        # engine's chooseShot falls back to a fixed angle when no candidate
        # clears the net, which is a self-inflicted lost point.
        ok = False
        if traj:
            lx, ly = traj[-1][1], traj[-1][2]
            if facing > 0:
                ok = (lx > R["netX"] + 0.05) and (lx < R["courtLength"] + 0.15)
            else:
                ok = (lx < R["netX"] - 0.05) and (lx > -0.15)
        if not ok:
            score -= 400.0
        score += min(cand["margin"], 0.38) * 30.0
        return score, shot, traj

    # ------------------------------------------------------------------
    # Verification: simulate our own inputs against the predicted ball
    # ------------------------------------------------------------------
    def _verify_hit(self, me, inputs, pred, team, nframes):
        """Return (frame, ball, held_move, swing_type) for the first real contact."""
        traj = sim_player(me, inputs, nframes)
        for f in range(1, min(nframes, len(traj) - 1) + 1):
            p = traj[f]
            if not in_window(p):
                continue
            rx, ry = E.Match.racket_at(p, p["swingElapsed"], p["swingType"])
            reach = reach_of(p["stamina"])
            samples = pred[f] if f < len(pred) else []
            for (bx, by, alive) in samples:
                if not alive:
                    continue
                if team == 0 and bx > R["netX"] + 0.3:
                    continue
                if team == 1 and bx < R["netX"] - 0.3:
                    continue
                if math.hypot(bx - rx, by - ry) <= reach:
                    mv = float(inputs[f - 1].get("move", 0.0)) if f - 1 < len(inputs) else 0.0
                    return f, (bx, by), mv, p["swingType"]
        return None

    @staticmethod
    def _shot_is_safe(traj, facing):
        if not traj:
            return False
        lx = traj[-1][1]
        if facing > 0:
            return (lx > R["netX"] + 0.05) and (lx < R["courtLength"] + 0.15)
        return (lx < R["netX"] - 0.05) and (lx > -0.15)

    # ------------------------------------------------------------------
    # Window construction
    # ------------------------------------------------------------------
    def _build_inputs(self, me, cand, hold_until=0, hold_x=None, nudge=False):
        t = cand["t"]
        e = cand["e"]
        horizon = max(10, t + 1)
        if hold_until > 0 and hold_x is not None and hold_until < t:
            seg1 = servo_inputs(me, hold_x, hold_until, nframes=hold_until, hold_after=False)
            cur = sim_player(me, seg1, len(seg1))[-1]
            rem = t - hold_until
            seg2 = servo_inputs(cur, cand["px"], rem, nframes=max(1, rem), hold_after=False)
            inputs = seg1 + seg2
        else:
            inputs = plan_control(me, cand["px"], t, horizon, hold_after=False)
        if me["swing"] <= 0:
            idx = (t - e) - 1
            if 0 <= idx < len(inputs):
                inputs[idx]["swing"] = cand["swtype"]
                if nudge:
                    inputs[idx]["move"] = float(me["facing"])
                    inputs[idx]["sprint"] = False
        return inputs

    @staticmethod
    def _format(inputs):
        out = []
        for i in range(10):
            inp = inputs[i] if i < len(inputs) else E.neutral()
            out.append({"move": round(float(inp.get("move", 0.0)), 4),
                        "jump": bool(inp.get("jump", False)),
                        "swing": int(inp.get("swing", 0)),
                        "sprint": bool(inp.get("sprint", False)),
                        "charge": False})
        return out

    def _hold_window(self, me, team, target_x=None):
        if target_x is None:
            return [{"move": 0.0, "jump": False, "swing": 0, "charge": False,
                     "sprint": False} for _ in range(10)]
        inputs = plan_control(me, target_x, 10, 10, hold_after=False)
        return self._format(inputs)

    # ------------------------------------------------------------------
    # Serve receiving: attack the serve
    # ------------------------------------------------------------------
    def _receive_serve(self, obs, me, opp, team):
        ball = obs["shuttle"]
        rel = int(round(float(obs.get("serveLeft", 0)) * R["hz"]))
        server_facing = 1 if obs.get("server") == 0 else -1
        pred = predict_serve(ball, rel, server_facing, 46)
        got = self._intercept(obs, me, opp, team, pred, budget=10, early_bias=0.4)
        if got is not None:
            return got
        return self._hold_window(me, team)

    # ------------------------------------------------------------------
    # Defence: force the short smash at the tie point, then chase it
    # ------------------------------------------------------------------
    def _tie_x(self, team):
        if self.def_mode == "camp":
            return 6.35 if team == 0 else R["netX"] + 0.35
        if self.def_mode == "mid":
            return 4.0 if team == 0 else R["courtLength"] - 4.0
        return 2.95 if team == 0 else 10.45

    def _defend(self, obs, me, opp, team):
        ball = obs["shuttle"]
        if obs.get("phase") == "serve":
            rel = int(round(float(obs.get("serveLeft", 0)) * R["hz"]))
            server_facing = 1 if obs.get("server") == 0 else -1
            pred = predict_serve(ball, rel, server_facing, 52)
        else:
            pred = predict_shuttle(ball, 52)
        tie = self._tie_x(team)
        opp_team = 1 - team
        if ball.get("lastTeam") == opp_team and obs.get("phase") != "serve":
            got = self._intercept(obs, me, opp, team, pred, budget=10)
            if got is not None:
                return got
            return self._hold_window(me, team, tie)
        # project the opponent's attack
        me_pred = dict(me)
        me_pred["x"] = tie
        me_pred["vx"] = 0.0
        projected = None
        if self.learn and obs.get("phase") == "serve" and obs.get("server") == team:
            learned = self._learned_contact()
            if learned is not None:
                cx, cy, off = learned
                rel = int(round(float(obs.get("serveLeft", 0)) * R["hz"]))
                t_learn = rel + off
                if 1 <= t_learn <= 40:
                    projected = self._project_from_contact(pred, cx, cy, t_learn, me_pred, opp, team)
                    if projected is not None:
                        log("learned opp contact (%.2f,%.2f) t=%d" % (cx, cy, t_learn))
        if projected is None:
            projected = self._project_opponent(pred, me_pred, opp, team)
        if projected is not None:
            t_contact, variants = projected
            if 1 <= t_contact <= 40:
                got = self._intercept(obs, me, opp, team, variants[0], budget=12,
                                      only_after=max(1, t_contact),
                                      hold_until=t_contact, hold_x=tie,
                                      variants=variants)
                if got is not None:
                    return got
                land = self._predicted_landing(variants[0])
                if land is not None:
                    lo = 0.35 if team == 0 else R["netX"] + 0.35
                    hi = R["netX"] - 0.35 if team == 0 else R["courtLength"] - 0.35
                    return self._hold_window(me, team, clamp(land, lo, hi))
        return self._hold_window(me, team, tie)

    @staticmethod
    def _predicted_landing(pred):
        for f in range(len(pred) - 1, 0, -1):
            for (bx, by, alive) in pred[f]:
                if not alive:
                    return bx
        return None

    def _project_from_contact(self, pred, cx, cy, t, me, opp, team):
        opp_team = 1 - team
        swtype = 1 if cy > 1.2 else -1
        ms = max_speed_of(opp["stamina"])
        est_fwd = 0.0
        forwards = [0.0, 0.5, 1.0]
        variants = []
        for fwd in forwards:
            sh = shot_from_contact(cx, cy, swtype, opp["facing"], me["x"], forward=fwd)
            sf = shot_frames(cx, cy, sh, opp["facing"], 55)
            combined = []
            for f in range(t + 56):
                if f < t:
                    combined.append(pred[f] if f < len(pred) else [(cx, cy, False)])
                else:
                    k = f - t
                    combined.append(sf[k] if k < len(sf) else [(cx, cy, False)])
            variants.append(combined)
        return t, variants

    def _project_opponent(self, pred, me, opp, team):
        opp_team = 1 - team
        cands = self._candidates(pred, opp, opp_team, 40)
        if not cands:
            return None
        best = None
        for c in cands:
            lo, hi = self._reachable_range(opp, c["t"])
            if c["px"] < lo - 0.08 or c["px"] > hi + 0.08:
                continue
            score, shot, traj = self._eval_contact(c, opp, me, opp_team, pred)
            score -= c["t"] * 0.4
            if best is None or score > best[0]:
                best = (score, c, shot)
        if best is None:
            return None
        _, c, shot = best
        t = c["t"]
        # The struck shuttle also gets a forward nudge from the striker's held
        # move; model a few possibilities so the plan is robust.
        ms = max_speed_of(opp["stamina"])
        est_fwd = clamp((opp["vx"] / ms) * opp["facing"], 0.0, 1.0) if ms > 1e-6 else 0.0
        forwards = []
        for f in (0.0, est_fwd, 1.0):
            if all(abs(f - g) > 0.2 for g in forwards):
                forwards.append(f)
        variants = []
        for fwd in forwards:
            sh = shot_from_contact(c["bx"], c["by"], c["swtype"], opp["facing"],
                                   me["x"], forward=fwd)
            sf = shot_frames(c["bx"], c["by"], sh, opp["facing"], 55)
            combined = []
            for f in range(t + 56):
                if f < t:
                    combined.append(pred[f] if f < len(pred) else [(c["bx"], c["by"], False)])
                else:
                    k = f - t
                    combined.append(sf[k] if k < len(sf) else [(c["bx"], c["by"], False)])
            variants.append(combined)
        log("project opp: t=%d e=%d type=%d at (%.2f,%.2f) -> %s fwd=%s" % (
            t, c["e"], c["swtype"], c["bx"], c["by"], shot["kind"],
            [round(x, 2) for x in forwards]))
        return t, variants

    # ------------------------------------------------------------------
    # Generic interception
    # ------------------------------------------------------------------
    def _intercept(self, obs, me, opp, team, pred, budget=10, only_after=0,
                   hold_until=0, hold_x=None, early_bias=0.3, variants=None):
        preds = [pred] if not variants else variants
        cands = self._candidates(pred, me, team, min(42, len(pred) - 1))
        scored = []
        for c in cands:
            if c["t"] < only_after:
                continue
            lo, hi = self._reachable_range(me, c["t"])
            if c["px"] < lo - 0.06 or c["px"] > hi + 0.06:
                continue
            score, shot, traj = self._eval_contact(c, me, opp, team, pred)
            score -= c["t"] * early_bias
            scored.append((score, c, shot))
        scored.sort(key=lambda x: -x[0])
        best = None
        for score, c, shot in scored[:budget]:
            inputs = self._build_inputs(me, c, hold_until, hold_x,
                                        nudge=(self.nudge and only_after == 0 and hold_until == 0))
            hits = []
            for pv in preds:
                hits.append(self._verify_hit(me, inputs, pv, team, max(12, c["t"] + 2)))
            good = sum(1 for h in hits if h is not None)
            if good == 0:
                continue
            # Re-evaluate the shot exactly as the engine will strike it (the
            # held move nudges the target) and drop self-destructive shots.
            h0 = hits[0]
            fwd = clamp(h0[2] * me["facing"], 0.0, 1.0)
            real = shot_from_contact(h0[1][0], h0[1][1], h0[3], me["facing"],
                                     opp_x_at(opp, h0[0]), forward=fwd)
            real_traj = simulate_shot(h0[1][0], h0[1][1], real, me["facing"], nframes=60)
            if not self._shot_is_safe(real_traj, me["facing"]):
                score -= 400.0
                if score < 0:
                    continue
            rank = (good, score)
            if best is None or rank > best[0]:
                best = (rank, inputs, c, shot, hits, score)
            if good == len(preds):
                break
        if best is None:
            return None
        rank, inputs, c, shot, hits, score = best
        log("intercept: t=%d e=%d type=%d px=%.2f score=%.1f %s cover=%d/%d hit@%s" % (
            c["t"], c["e"], c["swtype"], c["px"], score, shot["kind"],
            rank[0], len(preds), [h[0] if h else None for h in hits]))
        return self._format(inputs)

    # ------------------------------------------------------------------
    # Rally
    # ------------------------------------------------------------------
    def _rally_plan(self, obs, me, opp, team):
        ball = obs["shuttle"]
        pred = predict_shuttle(ball, 46)
        land = None
        for f in range(len(pred) - 1, 0, -1):
            for (bx, by, alive) in pred[f]:
                if not alive:
                    land = (bx, by)
                    break
            if land:
                break
        if land is not None:
            if team == 0 and land[0] < -0.1:
                return self._hold_window(me, team, 4.0)
            if team == 1 and land[0] > R["courtLength"] + 0.1:
                return self._hold_window(me, team, R["courtLength"] - 4.0)
        got = self._intercept(obs, me, opp, team, pred)
        if got is not None:
            return got
        tx = None
        for f in range(1, len(pred) - 1):
            for (bx, by, alive) in pred[f]:
                if not alive:
                    tx = bx
                    break
            if tx is not None:
                break
        if tx is not None:
            return self._hold_window(me, team, clamp(tx, 0.35 if team == 0 else 7.05,
                                                    6.35 if team == 0 else 13.05))
        return self._hold_window(me, team)

# ===================== main loop =====================





def _neutral():
    return {"move": 0.0, "jump": False, "swing": 0, "charge": False, "sprint": False}


def main():
    try:
        sys.stdin.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass
    try:
        sys.stdout.reconfigure(encoding="utf-8", newline="\n")
    except Exception:
        pass
    brain = Brain()
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            obs = json.loads(line)
        except Exception:
            obs = {}
        try:
            frames = brain.act(obs)
            if not isinstance(frames, list) or len(frames) != 10:
                raise ValueError("bad window")
            payload = []
            for f in frames:
                if not isinstance(f, dict):
                    raise ValueError("bad frame")
                payload.append([{
                    "move": float(f.get("move", 0.0)),
                    "jump": bool(f.get("jump", False)),
                    "swing": int(f.get("swing", 0)),
                    "charge": bool(f.get("charge", False)),
                    "sprint": bool(f.get("sprint", False)),
                }])
        except Exception:
            payload = [[_neutral()] for _ in range(10)]
        out.write(json.dumps({"inputs": payload}, separators=(",", ":")) + "\n")
        out.flush()


if __name__ == "__main__":
    main()